// provideAppWithCron 提供应用，包含定时任务启动和停止
func provideAppWithCron(
	logger log.Logger,
	gs *grpc.Server,
	hs *http.Server,
	archiveUsecase *biz.ArchiveUsecase,
	partitionUsecase *biz.PartitionUsecase,
	asynqServer *asynq.Server,
	taskHandler *biz.TaskHandler,
	archiveScheduler *service.ArchiveTaskScheduler,
) (*kratos.App, func(), error) {

	asynqServer.RegisterHandler(asynq.TaskTypeSQLOrderExecute, taskHandler.HandleSQLOrderExecute)
	asynqServer.RegisterHandler(asynq.TaskTypeBinlogParse, taskHandler.HandleBinlogParse)
	asynqServer.RegisterHandler(asynq.TaskTypeRedisRDBParse, taskHandler.HandleRedisRDBParse)
	asynqServer.RegisterHandler(asynq.TaskTypeArchiveExecute, taskHandler.HandleArchiveExecute)

	archiveUsecase.SetScheduler(archiveScheduler)

	go func() {
		if err := asynqServer.Start(); err != nil {
			log.NewHelper(logger).Errorf("Asynq服务器启动失败: %v", err)
		}
	}()

	app := kratos.New(kratos.ID("sisyphus"), kratos.Name("sisyphus"), kratos.Version("v1.0.0"), kratos.Metadata(map[string]string{}), kratos.Logger(logger), kratos.Server(
		gs,
		hs,
	),
	)

	ctx := context.Background()
	if err := archiveUsecase.StartCron(ctx); err != nil {
		return nil, nil, err
	}
	if err := partitionUsecase.StartCron(ctx); err != nil {
		return nil, nil, err
	}

	return app, func() {

		archiveUsecase.StopCron()
		partitionUsecase.StopCron()

		asynqServer.Shutdown()
	}, nil
}
